package hu.bankmonitor.payments.transfers.checks;

import hu.bankmonitor.payments.transfers.Transfer;
import org.springframework.stereotype.Component;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

import java.util.Objects;

/**
 * The per-Transfer record of which Checks it requires and how each has been answered, and
 * the one operation this package exports today: opening that record.
 *
 * <p>The whole of what the Check Ledger is for rests on it being written <em>with</em> the
 * Transfer. A Transfer whose rows were written afterwards has a window in which it is
 * {@code PENDING} against an empty checklist — which is a Transfer nothing will ever
 * settle, expire or explain, holding an operator's funds until somebody notices. {@link
 * Propagation#MANDATORY} is that requirement stated to the container rather than left as a
 * convention for the caller to honour: this method cannot start a transaction of its own,
 * so the only way to call it is from inside one that is already writing the Transfer.
 *
 * <p>The method is public on a package-private-by-default design because {@code
 * @Transactional} on a non-public method is silently ignored under proxy-based AOP — the
 * trap {@link hu.bankmonitor.payments} documents. The class is public for the ordinary
 * reason: {@code FundsReservation} is in the parent package and has to name it.
 */
@Component
public class CheckLedger {

	private final CheckPolicy policy;

	private final CheckLedgerRepository entries;

	CheckLedger(CheckPolicy policy, CheckLedgerRepository entries) {
		this.policy = policy;
		this.entries = entries;
	}

	/**
	 * Writes one outstanding row per Check the Transfer requires, in the caller's
	 * transaction.
	 *
	 * @param transfer a Transfer already written, so that the rows have an ID to point at
	 * @throws org.springframework.transaction.IllegalTransactionStateException if the caller
	 *                                                                         has no
	 *                                                                         transaction
	 *                                                                         open
	 */
	@Transactional(propagation = Propagation.MANDATORY)
	public void openFor(Transfer transfer) {
		Long transferId = Objects.requireNonNull(transfer.getId(), "a ledger belongs to a written transfer");

		for (Check required : policy.requiredFor(transfer)) {
			entries.save(CheckLedgerEntry.outstanding(transferId, required));
		}
	}
}

package hu.bankmonitor.payments.transfers.checks;

import java.util.Collection;

/**
 * What a Transfer's Check Ledger says should happen to the Transfer next.
 *
 * <p>{@link #decide} is the whole of the orchestration rule, and it is a function of the
 * ledger rows and nothing else — no repository, no clock, no Transfer. That is a design
 * instruction rather than a testing convenience: the same three lines inside a service that
 * also loads rows and moves money would only be reachable through a database, and the
 * mixed-verdict case that matters most would be set up by writing four tables.
 *
 * <p>Ticket 20 is the caller. It loads the rows, applies the answer here, and owns
 * everything with a side effect: a Transfer advances by conditional update, so two
 * deliveries of the same Verdict can both reach this function and only one of them can win
 * the write that follows.
 */
enum LedgerDecision {

	/** Every Check has approved. The money moves, once. */
	SETTLE,

	/** A Check said no. The reservation is released and no money ever moved. */
	REJECT,

	/** Some Check has not answered, and none has refused. Nothing happens. */
	WAIT;

	/**
	 * Reads a Transfer's Check Ledger and says what follows from it.
	 *
	 * <p><b>Rejection wins immediately</b>, which is why it is asked first: once one Check
	 * has said no there is nothing the outstanding ones could say that changes the outcome,
	 * and waiting for them would hold an operator's funds against a Transfer already known
	 * to be dead. So a ledger of one rejection and three unanswered rows is {@link #REJECT},
	 * not {@link #WAIT}.
	 *
	 * <p>The second question is only whether anything is still outstanding, because the
	 * first has already excluded every rejection: answered and not rejected is approved.
	 *
	 * @param ledger every row the Transfer has, in any order
	 * @throws IllegalArgumentException if the ledger is empty — see below
	 */
	static LedgerDecision decide(Collection<CheckLedgerEntry> ledger) {
		// An empty ledger satisfies "nothing outstanding, nothing rejected" and would settle
		// a Transfer nobody checked. It cannot arise — a Transfer is written with its rows in
		// one transaction — so the only way to be handed one is to have loaded the wrong
		// Transfer's, and answering that with "move the money" is the worst available guess.
		if (ledger.isEmpty()) {
			throw new IllegalArgumentException("a transfer's check ledger is never empty");
		}
		if (ledger.stream().anyMatch(CheckLedgerEntry::isRejected)) {
			return REJECT;
		}
		return ledger.stream().allMatch(CheckLedgerEntry::isAnswered) ? SETTLE : WAIT;
	}
}

package hu.bankmonitor.payments.transfers.checks;

import hu.bankmonitor.payments.transfers.Transfer;
import org.springframework.stereotype.Component;

import java.util.EnumSet;
import java.util.Set;

/**
 * Which Checks a Transfer has to pass before it can settle.
 *
 * <p>The one place that answer is given. Adding a condition to this payment gateway is a
 * constant on {@link Check}, a line here and a row in the ledger — no new endpoint, no new
 * state, and nothing in the settlement rule to revisit. That extensibility is the whole
 * reason ADR-0001 chose an asynchronous lifecycle over settling inside the request.
 */
@Component
class CheckPolicy {

	/**
	 * Every Transfer requires both Checks today, so the Transfer goes unread — and the
	 * parameter is still the point. A policy that cannot see the Transfer cannot grow the
	 * first rule that depends on one ("manual approval above ten thousand", "fraud
	 * screening only across Currencies"), and this ticket is the one that gets to choose
	 * the signature while it has no other caller to break.
	 *
	 * <p>Deliberately not {@code EnumSet.allOf(Check.class)}, which would be shorter and
	 * would silently apply the first conditional Check to every Transfer ever written. What
	 * Checks <em>exist</em> and what a given Transfer <em>requires</em> are two questions,
	 * and this class only answers the second.
	 */
	Set<Check> requiredFor(Transfer transfer) {
		return EnumSet.of(Check.FRAUD, Check.MANUAL_APPROVAL);
	}
}

