1	package hu.bankmonitor.payments.transfers.checks;
2	
3	import org.junit.jupiter.api.DisplayName;
4	import org.junit.jupiter.api.Test;
5	
6	import java.util.List;
7	
8	import static hu.bankmonitor.payments.transfers.checks.Check.FRAUD;
9	import static hu.bankmonitor.payments.transfers.checks.Check.MANUAL_APPROVAL;
10	import static hu.bankmonitor.payments.transfers.checks.LedgerDecision.REJECT;
11	import static hu.bankmonitor.payments.transfers.checks.LedgerDecision.SETTLE;
12	import static hu.bankmonitor.payments.transfers.checks.LedgerDecision.WAIT;
13	import static hu.bankmonitor.payments.transfers.checks.Verdict.APPROVED;
14	import static hu.bankmonitor.payments.transfers.checks.Verdict.REJECTED;
15	import static org.assertj.core.api.Assertions.assertThat;
16	import static org.assertj.core.api.Assertions.assertThatThrownBy;
17	
18	/**
19	 * The orchestration rule, as a table of ledgers and what each one means.
20	 *
21	 * <p><b>No Spring context, no database, no clock</b> — which is the reason {@link
22	 * LedgerDecision#decide} was specified as a function over rows rather than as a step inside
23	 * the service that records a Verdict. Every case below is one line of setup; inside a
24	 * service the mixed ledger alone would be two Accounts, a Transfer and four rows written
25	 * through three slices, and the case most likely to be wrong would be the one most
26	 * expensive to write.
27	 */
28	class LedgerDecisionTest {
29	
30		private static final long ANY_TRANSFER = 1L;
31	
32		@Test
33		@DisplayName("a ledger with every Check approved settles")
34		void settlesWhenEveryCheckHasApproved() {
35			assertThat(LedgerDecision.decide(List.of(
36					answered(FRAUD, APPROVED),
37					answered(MANUAL_APPROVAL, APPROVED))))
38					.isEqualTo(SETTLE);
39		}
40	
41		@Test
42		@DisplayName("one rejection rejects, whatever the other Checks said")
43		void rejectsWhenOneCheckRejectedAndAnotherApproved() {
44			assertThat(LedgerDecision.decide(List.of(
45					answered(FRAUD, APPROVED),
46					answered(MANUAL_APPROVAL, REJECTED))))
47					.isEqualTo(REJECT);
48		}
49	
50		/**
51		 * The claim the ordering of the two questions exists for. A ledger that is neither
52		 * complete nor clean is a rejection, not a wait: nothing an outstanding Check could say
53		 * would revive the Transfer, so holding the reservation open for it costs the operator
54		 * money for no possible outcome.
55		 */
56		@Test
57		@DisplayName("a rejection wins immediately, without waiting for the outstanding Checks")
58		void rejectsWhileAnotherCheckIsStillOutstanding() {
59			assertThat(LedgerDecision.decide(List.of(
60					answered(FRAUD, REJECTED),
61					outstanding(MANUAL_APPROVAL))))
62					.isEqualTo(REJECT);
63		}
64	
65		@Test
66		@DisplayName("a ledger nobody has answered waits")
67		void waitsWhenNoCheckHasAnswered() {
68			assertThat(LedgerDecision.decide(List.of(
69					outstanding(FRAUD),
70					outstanding(MANUAL_APPROVAL))))
71					.isEqualTo(WAIT);
72		}
73	
74		@Test
75		@DisplayName("a ledger part answered and part outstanding waits")
76		void waitsWhenOneCheckHasApprovedAndAnotherHasNotAnswered() {
77			assertThat(LedgerDecision.decide(List.of(
78					answered(FRAUD, APPROVED),
79					outstanding(MANUAL_APPROVAL))))
80					.isEqualTo(WAIT);
81		}
82	
83		/**
84		 * A single approval settling a one-row ledger is the same rule and not a special case,
85		 * which is what makes "a new Check is a line in the policy" true: the decision counts
86		 * rows, it does not know how many there ought to be.
