package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.common.Currency;
import hu.bankmonitor.testsupport.BootedApplicationTest;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.jdbc.core.JdbcTemplate;

import java.time.Instant;
import java.util.List;
import java.util.Map;

/**
 * The Accounts, the reads and the cleanup the two reservation tests share.
 *
 * <p><b>Nothing here is transactional, and that is the point.</b> A {@code @Transactional}
 * test method makes every write it performs invisible to any other connection and rolls the
 * lot back at the end — which would leave
 * {@link ConcurrentReservationsHoldTheBalanceTest}'s second thread unable to see the first
 * thread's reservation, and every assertion in
 * {@link ReservedFundsReachTheTableTest} agreeing with a transaction that never committed.
 * Both classes need real commits, so the price is paying for the cleanup by hand.
 *
 * <p>The tables are emptied before each method as well as after: one in-memory H2 database is
 * shared by every test in the suite, whichever application context booted it, and the
 * assertions below count rows rather than looking only at their own.
 *
 * <p>Rows go in and come back out in SQL rather than through the entities, so what is
 * asserted is what reached the database — a round trip through the mapping under test would
 * agree with itself whatever it wrote.
 */
abstract class ReservationScenario extends BootedApplicationTest {

	static final Instant REQUESTED_AT = Instant.parse("2026-09-05T10:15:30Z");

	@Autowired
	FundsReservation reservation;

	@Autowired
	JdbcTemplate database;

	/** Ledger first, then Transfers, then Accounts: each table points at the one below it. */
	@BeforeEach
	@AfterEach
	void emptyTheTablesTheseTestsWriteTo() {
		database.update("DELETE FROM check_ledger");
		database.update("DELETE FROM transfers");
		database.update("DELETE FROM accounts");
	}

	/**
	 * With an explicit identifier, which the identity column accepts because it is declared
	 * {@code generated by default}. The lock order is ascending by ID, so a test about two
	 * Accounts needs to be able to say which of them is the lower one.
	 */
	void openAccount(long id, long balanceMinorUnits, Currency currency) {
		database.update("""
				INSERT INTO accounts (id, balance_minor_units, balance_currency,
				                      reserved_amount_minor_units, reserved_amount_currency)
				VALUES (?, ?, ?, 0, ?)
				""", id, balanceMinorUnits, currency.name(), currency.name());
	}

	/**
	 * Reads as the sentence a Transfer is — an amount, out of one Account, into another —
	 * which is deliberately not the order {@link ReservationRequest} declares its components
	 * in. Three adjacent {@code long}s are swappable in silence either way; naming the two
	 * Accounts {@code from} and {@code to} is what makes a swapped call read wrong.
	 */
	static ReservationRequest transferOf(long amountMinorUnits, long fromAccountId, long toAccountId) {
		return new ReservationRequest(fromAccountId, toAccountId, amountMinorUnits, REQUESTED_AT);
	}

	long balanceOf(long accountId) {
		return minorUnitsOf("balance_minor_units", accountId);
	}

	long reservedAmountOf(long accountId) {
		return minorUnitsOf("reserved_amount_minor_units", accountId);
	}

	/** What an overdraft check tests against, read back from the two columns it is derived from. */
	long availableBalanceOf(long accountId) {
		return balanceOf(accountId) - reservedAmountOf(accountId);
	}

	List<Map<String, Object>> transferRows() {
		return database.queryForList("SELECT * FROM transfers ORDER BY id");
	}

	List<Map<String, Object>> checkLedgerRows() {
		return database.queryForList("SELECT * FROM check_ledger ORDER BY id");
	}

	private long minorUnitsOf(String column, long accountId) {
		Long minorUnits = database.queryForObject(
				"SELECT " + column + " FROM accounts WHERE id = ?", Long.class, accountId);
		return minorUnits == null ? 0L : minorUnits;
	}
}

package hu.bankmonitor.payments.transfers.checks;

import org.springframework.data.repository.Repository;

/**
 * Persistence for {@link CheckLedgerEntry}, package-private so that reaching it from
 * another slice does not compile (design decision 30).
 *
 * <p>The bare {@link Repository} marker rather than {@code JpaRepository}, on {@code
 * Account}'s precedent: it declares nothing, so every method here is one with a call site
 * today. The two this design will need — the read that a Verdict's decision is made over,
 * and the update guarded on the row still being unanswered — arrive with ticket 20, which
 * is the first thing with a question to ask of them.
 */
interface CheckLedgerRepository extends Repository<CheckLedgerEntry, Long> {

	/** Opens one Check on one Transfer, which is how a ledger row comes to exist. */
	CheckLedgerEntry save(CheckLedgerEntry entry);
}

package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.accounts.AccountLocking;
import hu.bankmonitor.payments.accounts.LockedAccounts;
import hu.bankmonitor.payments.common.Money;
import hu.bankmonitor.payments.transfers.checks.CheckLedger;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Requests a Transfer: funds reserved on the source Account, nothing moved, and a {@code
 * PENDING} Transfer to hold the request while its Checks are outstanding.
 *
 * <p><b>The order inside {@link #reserve} is the correctness argument</b>, and it is the
 * reason the three statements are not interchangeable:
 *
 * <ol>
 * <li>lock both Accounts, ascending by ID, which {@link AccountLocking} owns;
 * <li><em>then</em> read the source Account's Available Balance and test the amount against
 * it;
 * <li>write the reservation, the Transfer, and the Check Ledger the Transfer will be
 * settled or rejected against.
 * </ol>
 *
 * <p>Because the check follows the lock, the figure it tests against cannot be invalidated
 * between reading it and acting on it: any other transaction that would spend the same
 * Available Balance is waiting on the row until this one commits, and then reads what this
 * one wrote. Checking first and locking second would compile, pass every single-threaded
 * test, and overdraw under load.
 *
 * <p>Nothing here saves the source Account, and that is not an omission. The Accounts come
 * back from {@link AccountLocking} attached to this transaction's persistence context, so
 * raising the Reserved Amount <em>is</em> the write, flushed on commit alongside the
 * Transfer. There is no other way for this slice to do it either: design decision 30 keeps
 * {@code AccountRepository} package-private, and locking is the whole of what {@code
 * accounts} exports.
 *
 * <p>The Exchange Rate is deliberately not fetched here. Design decision 4 puts it in a
 * phase of its own with no transaction open and no locks held, which is what makes
 * pessimistic locking affordable at all; {@code LockedPathTouchesOnlyTheDatabaseTest} names
 * this class and fails if anything it can reach would wait on a provider.
 *
 * <p><b>Same-Currency Transfers only, and not by a check.</b> Both amounts on the Transfer
 * are denominated by the source Account, so a Transfer between two Currencies is reserved
 * and written with the wrong Currency in the credited column rather than refused. That hole
 * is deliberate and named in {@code docs/deferred.md}: ticket 26 is where an Exchange Rate
 * gives the credited side a figure of its own, and a refusal added here now is a rule ticket
 * 26 would have to reinterpret rather than delete.
 */
@Service
class FundsReservation {

	private final AccountLocking accounts;

	private final TransferRepository transfers;

	private final CheckLedger ledger;

	FundsReservation(AccountLocking accounts, TransferRepository transfers, CheckLedger ledger) {
		this.accounts = accounts;
		this.transfers = transfers;
		this.ledger = ledger;
	}

	/**
	 * Reserves the amount on the source Account and records the {@code PENDING} Transfer it
	 * is held for, in one transaction that writes both or neither.
	 *
	 * <p>The transaction is opened here rather than inherited, which is what {@link
	 * AccountLocking}'s mandatory propagation is checking for. Ticket 16 will widen it to
	 * carry the idempotency record's flip to {@code SUCCEEDED} in the same commit, per
	 * design decision 4.
	 *
	 * <p>The Check Ledger is opened last because its rows point at the Transfer's ID, and
	 * inside the same transaction because a {@code PENDING} Transfer with an empty checklist
	 * is one nothing will ever settle, expire or explain. {@link CheckLedger#openFor} refuses
	 * to run without a transaction, so the ordering is the only part of that left here.
	 *
	 * @throws hu.bankmonitor.payments.accounts.UnknownAccountException  if either Account ID
	 *                                                                  has no row
	 * @throws hu.bankmonitor.payments.accounts.InsufficientFundsException if the source
	 *                                                                  Account's Available
	 *                                                                  Balance does not
	 *                                                                  cover the amount
	 * @throws IllegalArgumentException if both IDs name the same Account
	 */
	@Transactional
	public Transfer reserve(ReservationRequest request) {
		LockedAccounts locked =
				accounts.lockForTransfer(request.sourceAccountId(), request.destinationAccountId());
		Money amount = new Money(request.amountMinorUnits(), locked.source().getCurrency());

		locked.source().reserve(amount);

		Transfer requested = transfers.save(new Transfer(request.sourceAccountId(),
				request.destinationAccountId(), amount, amount, request.requestedAt()));
		ledger.openFor(requested);
		return requested;
	}
}

package hu.bankmonitor.payments.transfers;

import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.lang.ArchRule;
import hu.bankmonitor.testsupport.boundaryviolations.secondwriter.SecondTransferWriter;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.noClasses;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * What makes "a Transfer without its Check Ledger is impossible" a structural claim rather
 * than a description of the one path that exists today.
 *
 * <p>{@code EveryTransferOpensItsCheckLedgerTest} shows that {@link FundsReservation}
 * writes both. That is a claim about a path, and a second path would not make it false —
 * a settlement retry, a fixture, a back-office correction tool, anything that saved a
 * {@code Transfer} of its own would produce the {@code PENDING} row with an empty ledger
 * that the whole design is arranged to prevent, and every existing test would stay green.
 *
 * <p>So the rule is about the write rather than about the ledger: a Transfer comes into
 * being in exactly one place, and that place opens the ledger unconditionally in the same
 * transaction. The compiler already stops another <em>slice</em> — {@link
 * TransferRepository} is package-private per design decision 30 — and this covers the
 * inside of {@code transfers}, which is where the second writer would actually be added.
 *
 * <p><b>What it does not claim.</b> Not that {@code FundsReservation} opens the ledger; that
 * is the booted test's, and this rule would stay green if the call were deleted. The two
 * are halves of one argument and neither is worth much alone.
 */
class NothingButTheReservationCreatesATransferTest {

	/**
	 * By dependency rather than by call, because {@link TransferRepository} has exactly one
	 * write method and a class that holds the repository at all is one edit away from
	 * calling it. Matching the type also survives the query methods tickets 15, 20 and 23
	 * will add to it, which a rule naming {@code save} would not.
	 */
	private static final ArchRule ONLY_THE_RESERVATION_WRITES_A_TRANSFER = noClasses()
			.that().doNotHaveFullyQualifiedName(FundsReservation.class.getName())
			.should().dependOnClassesThat().haveFullyQualifiedName(TransferRepository.class.getName())
			.because("a Transfer written anywhere else would be PENDING against an empty check ledger");

	@Test
	@DisplayName("a Transfer comes into being in exactly one place")
	void onlyTheReservationWritesATransfer() {
		ONLY_THE_RESERVATION_WRITES_A_TRANSFER.check(new ClassFileImporter()
				.withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
				.importPackages("hu.bankmonitor.payments"));
	}

	/**
	 * The rule against code that breaks it, on {@code ModuleBoundariesHoldTest}'s reasoning:
	 * a prohibition that has quietly stopped matching anything passes just as greenly as one
	 * that holds.
	 */
	@Test
	@DisplayName("a second class holding the repository is reported, by name")
	void detectsASecondWriter() {
		JavaClasses secondWriter = new ClassFileImporter()
				.importPackages(SecondTransferWriter.class.getPackageName());

		assertThatThrownBy(() -> secondWriterRule().check(secondWriter))
				.isInstanceOf(AssertionError.class)
				.hasMessageContaining("SecondTransferWriter");
	}

	/**
	 * The same rule aimed at the fixture's own repository. It has to be restated rather than
	 * reused, because {@link #ONLY_THE_RESERVATION_WRITES_A_TRANSFER} names two production
	 * classes the fixture package does not contain — which is exactly why the fixture is a
	 * separate package rather than a class beside the real ones.
	 */
	private static ArchRule secondWriterRule() {
		return noClasses()
				.that().doNotHaveSimpleName("FundsReservation")
				.should().dependOnClassesThat().haveSimpleName("TransferStore");
	}
}

