package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.accounts.InsufficientFundsException;
import hu.bankmonitor.payments.common.Money;
import hu.bankmonitor.payments.transfers.checks.CheckLedger;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.transaction.IllegalTransactionStateException;

import static hu.bankmonitor.payments.common.Currency.EUR;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * That a Transfer and the checklist it will be settled against are written together, or
 * neither is.
 *
 * <p>The failure this is aimed at is quiet rather than loud. A ledger opened <em>after</em>
 * the Transfer's transaction commits, or skipped on some second path that creates a
 * Transfer, leaves a {@code PENDING} row with an empty ledger — and an empty ledger has no
 * outstanding Check to answer, so nothing settles it, nothing rejects it, and the support
 * question "why is this stuck" has no answer to find. The funds stay reserved until a person
 * notices.
 *
 * <p>Two of the three claims here are structural rather than behavioural: {@link
 * CheckLedger#openFor} refuses to run outside a transaction, and {@code
 * NothingButTheReservationCreatesATransferTest} holds that there is no second path. What is
 * left for a booted test is that the one path writes what it should.
 *
 * <p>Rows come back in SQL rather than through the entities for {@link ReservationScenario}'s
 * reason: a round trip through the mapping under test would agree with itself whatever it
 * wrote.
 */
class EveryTransferOpensItsCheckLedgerTest extends ReservationScenario {

	private static final long SOURCE = 1L;
	private static final long DESTINATION = 2L;
	private static final long OPENING_BALANCE = 250_00L;

	@Autowired
	private CheckLedger ledger;

	@BeforeEach
	void openBothAccounts() {
		openAccount(SOURCE, OPENING_BALANCE, EUR);
		openAccount(DESTINATION, 0L, EUR);
	}

	@Test
	@DisplayName("requesting a Transfer opens one outstanding row per required Check")
	void opensOneOutstandingRowPerRequiredCheck() {
		Transfer requested = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));

		assertThat(checkLedgerRows())
				.allSatisfy(row -> {
					assertThat(row).containsEntry("TRANSFER_ID", requested.getId());
					assertThat(row).containsEntry("VERDICT", null);
				})
				.extracting(row -> row.get("REQUIRED_CHECK"))
				.containsExactlyInAnyOrder("FRAUD", "MANUAL_APPROVAL");
	}

	/**
	 * The two Transfers get a ledger each rather than sharing one, which is the difference
	 * between a checklist and a lookup of what a Check service has ever said.
	 */
	@Test
	@DisplayName("a second Transfer gets a ledger of its own")
	void opensASeparateLedgerForEachTransfer() {
		Transfer first = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));
		Transfer second = reservation.reserve(transferOf(30_00L, SOURCE, DESTINATION));

		assertThat(checkLedgerRows())
				.hasSize(4)
				.extracting(row -> row.get("TRANSFER_ID"))
				.containsOnly(first.getId(), second.getId());
	}

	@Test
	@DisplayName("a refused Transfer leaves no ledger behind either")
	void writesNoLedgerWhenTheTransferIsRefused() {
		assertThatThrownBy(() -> reservation.reserve(transferOf(OPENING_BALANCE + 1, SOURCE, DESTINATION)))
				.isInstanceOf(InsufficientFundsException.class);

		assertThat(transferRows()).isEmpty();
		assertThat(checkLedgerRows()).isEmpty();
	}

	/**
	 * Mandatory propagation asserted directly, rather than inferred from the fact that the
	 * one caller happens to be transactional. It is what stops the next caller — ticket 20's
	 * settlement, a fixture, a script — from opening a ledger that commits separately from
	 * the Transfer it belongs to.
	 */
	@Test
	@DisplayName("a ledger cannot be opened outside a transaction")
	void refusesToOpenALedgerWithNoTransaction() {
		Money euro = new Money(10_00L, EUR);
		Transfer unwritten = new Transfer(SOURCE, DESTINATION, euro, euro, REQUESTED_AT);

		assertThatThrownBy(() -> ledger.openFor(unwritten))
				.isInstanceOf(IllegalTransactionStateException.class);

		assertThat(checkLedgerRows()).isEmpty();
	}

	/**
	 * The check constraint doing its job, and not merely being present. {@code
	 * V4__check_ledger.sql} allows a null Verdict beside an {@code = any (array[…])} list,
	 * and the migration README records that the obvious way to write such a list is broken
	 * on H2 in a way that fails <em>every</em> insert. The tests above would catch that half;
	 * this catches the other, where the constraint accepts everything instead.
	 *
	 * <p>An update rather than an insert, and not incidentally: an insert of a bad Verdict
	 * for a Check the Transfer already has is refused by the uniqueness rule below before the
	 * constraint under test is ever consulted, which is a green test proving the wrong thing.
	 * It is also the shape ticket 20 will write a Verdict in.
	 */
	@Test
	@DisplayName("the table refuses a Verdict that is not one of the two")
	void refusesAVerdictTheDomainDoesNotHave() {
		reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));

		assertThatThrownBy(() -> database.update("UPDATE check_ledger SET verdict = 'MAYBE'"))
				.isInstanceOf(DataIntegrityViolationException.class);
	}

	/**
	 * One row per Check per Transfer, enforced where a Check service's retry will actually
	 * hit it. Ticket 20 makes at-least-once delivery safe by guarding the update on the row
	 * still being unanswered; that guard is only worth anything if a second delivery cannot
	 * simply write a second row instead.
	 */
	@Test
	@DisplayName("a Transfer cannot collect a second row for the same Check")
	void refusesASecondRowForACheckTheTransferAlreadyHas() {
		Transfer requested = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));

		assertThatThrownBy(() -> database.update("""
				INSERT INTO check_ledger (transfer_id, required_check, verdict)
				VALUES (?, 'FRAUD', 'APPROVED')
				""", requested.getId()))
				.isInstanceOf(DataIntegrityViolationException.class);
	}
}

package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.accounts.InsufficientFundsException;
import hu.bankmonitor.payments.common.Money;
import hu.bankmonitor.payments.transfers.checks.CheckLedger;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.transaction.IllegalTransactionStateException;

import static hu.bankmonitor.payments.common.Currency.EUR;
import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

/**
 * That a Transfer and the Check Ledger it will be settled against are written together, or
 * neither is.
 *
 * <p>The failure this is aimed at is quiet rather than loud. A ledger opened <em>after</em>
 * the Transfer's transaction commits, or skipped on some second path that creates a
 * Transfer, leaves a {@code PENDING} row with an empty ledger — and an empty ledger has no
 * outstanding Check to answer, so nothing settles it, nothing rejects it, and the support
 * question "why is this stuck" has no answer to find. The funds stay reserved until a person
 * notices.
 *
 * <p>Two of the three claims here are structural rather than behavioural: {@link
 * CheckLedger#openFor} refuses to run outside a transaction, and {@code
 * NothingButTheReservationCreatesATransferTest} holds that there is no second path. What is
 * left for a booted test is that the one path writes what it should.
 *
 * <p>Rows come back in SQL rather than through the entities for {@link ReservationScenario}'s
 * reason: a round trip through the mapping under test would agree with itself whatever it
 * wrote.
 */
class EveryTransferOpensItsCheckLedgerTest extends ReservationScenario {

	private static final long SOURCE = 1L;
	private static final long DESTINATION = 2L;
	private static final long OPENING_BALANCE = 250_00L;

	@Autowired
	private CheckLedger ledger;

	@BeforeEach
	void openBothAccounts() {
		openAccount(SOURCE, OPENING_BALANCE, EUR);
		openAccount(DESTINATION, 0L, EUR);
	}

	@Test
	@DisplayName("requesting a Transfer opens one outstanding row per required Check")
	void opensOneOutstandingRowPerRequiredCheck() {
		Transfer requested = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));

		assertThat(checkLedgerRows())
				.allSatisfy(row -> {
					assertThat(row).containsEntry("TRANSFER_ID", requested.getId());
					assertThat(row).containsEntry("VERDICT", null);
				})
				.extracting(row -> row.get("REQUIRED_CHECK"))
				.containsExactlyInAnyOrder("FRAUD", "MANUAL_APPROVAL");
	}

	/**
	 * The two Transfers get a ledger each rather than sharing one, which is the difference
	 * between a checklist and a lookup of what a Check service has ever said.
	 */
	@Test
	@DisplayName("a second Transfer gets a ledger of its own")
	void opensASeparateLedgerForEachTransfer() {
		Transfer first = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));
		Transfer second = reservation.reserve(transferOf(30_00L, SOURCE, DESTINATION));

		assertThat(checkLedgerRows())
				.hasSize(4)
				.extracting(row -> row.get("TRANSFER_ID"))
				.containsOnly(first.getId(), second.getId());
	}

	@Test
	@DisplayName("a refused Transfer leaves no ledger behind either")
	void writesNoLedgerWhenTheTransferIsRefused() {
		assertThatThrownBy(() -> reservation.reserve(transferOf(OPENING_BALANCE + 1, SOURCE, DESTINATION)))
				.isInstanceOf(InsufficientFundsException.class);

		assertThat(transferRows()).isEmpty();
		assertThat(checkLedgerRows()).isEmpty();
	}

	/**
	 * Mandatory propagation asserted directly, rather than inferred from the fact that the
	 * one caller happens to be transactional. It is what stops the next caller — ticket 20's
	 * settlement, a fixture, a script — from opening a ledger that commits separately from
	 * the Transfer it belongs to.
	 */
	@Test
	@DisplayName("a ledger cannot be opened outside a transaction")
	void refusesToOpenALedgerWithNoTransaction() {
		Money euro = new Money(10_00L, EUR);
		Transfer unwritten = new Transfer(SOURCE, DESTINATION, euro, euro, REQUESTED_AT);

		assertThatThrownBy(() -> ledger.openFor(unwritten))
				.isInstanceOf(IllegalTransactionStateException.class);

		assertThat(checkLedgerRows()).isEmpty();
	}

	/**
	 * The check constraint doing its job, and not merely being present. {@code
	 * V4__check_ledger.sql} allows a null Verdict beside an {@code = any (array[…])} list,
	 * and the migration README records that the obvious way to write such a list is broken
	 * on H2 in a way that fails <em>every</em> insert. The tests above would catch that half;
	 * this catches the other, where the constraint accepts everything instead.
	 *
	 * <p>An update rather than an insert, and not incidentally: an insert of a bad Verdict
	 * for a Check the Transfer already has is refused by the uniqueness rule below before the
	 * constraint under test is ever consulted, which is a green test proving the wrong thing.
	 * It is also the shape ticket 20 will write a Verdict in.
	 */
	@Test
	@DisplayName("the table refuses a Verdict that is not one of the two")
	void refusesAVerdictTheDomainDoesNotHave() {
		reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));

		assertThatThrownBy(() -> database.update("UPDATE check_ledger SET verdict = 'MAYBE'"))
				.isInstanceOf(DataIntegrityViolationException.class);
	}

	/**
	 * One row per Check per Transfer, enforced where a Check service's retry will actually
	 * hit it. Ticket 20 makes at-least-once delivery safe by guarding the update on the row
	 * still being unanswered; that guard is only worth anything if a second delivery cannot
	 * simply write a second row instead.
	 */
	@Test
	@DisplayName("a Transfer cannot collect a second row for the same Check")
	void refusesASecondRowForACheckTheTransferAlreadyHas() {
		Transfer requested = reservation.reserve(transferOf(80_00L, SOURCE, DESTINATION));

		assertThatThrownBy(() -> database.update("""
				INSERT INTO check_ledger (transfer_id, required_check, verdict)
				VALUES (?, 'FRAUD', 'APPROVED')
				""", requested.getId()))
				.isInstanceOf(DataIntegrityViolationException.class);
	}
}

package hu.bankmonitor.payments.transfers;

import hu.bankmonitor.payments.accounts.AccountLocking;
import hu.bankmonitor.payments.accounts.LockedAccounts;
import hu.bankmonitor.payments.common.Money;
import hu.bankmonitor.payments.transfers.checks.CheckLedger;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Requests a Transfer: funds reserved on the source Account, nothing moved, and a {@code
 * PENDING} Transfer to hold the request while its Checks are outstanding.
 *
 * <p><b>The order inside {@link #reserve} is the correctness argument</b>, and it is the
 * reason the three statements are not interchangeable:
 *
 * <ol>
 * <li>lock both Accounts, ascending by ID, which {@link AccountLocking} owns;
 * <li><em>then</em> read the source Account's Available Balance and test the amount against
 * it;
 * <li>write the reservation, the Transfer, and the Check Ledger the Transfer will be
 * settled or rejected against.
 * </ol>
 *
 * <p>Because the check follows the lock, the figure it tests against cannot be invalidated
 * between reading it and acting on it: any other transaction that would spend the same
 * Available Balance is waiting on the row until this one commits, and then reads what this
 * one wrote. Checking first and locking second would compile, pass every single-threaded
 * test, and overdraw under load.
 *
 * <p>Nothing here saves the source Account, and that is not an omission. The Accounts come
 * back from {@link AccountLocking} attached to this transaction's persistence context, so
 * raising the Reserved Amount <em>is</em> the write, flushed on commit alongside the
 * Transfer. There is no other way for this slice to do it either: design decision 30 keeps
 * {@code AccountRepository} package-private, and locking is the whole of what {@code
 * accounts} exports.
 *
 * <p>The Exchange Rate is deliberately not fetched here. Design decision 4 puts it in a
 * phase of its own with no transaction open and no locks held, which is what makes
 * pessimistic locking affordable at all; {@code LockedPathTouchesOnlyTheDatabaseTest} names
 * this class and fails if anything it can reach would wait on a provider.
 *
 * <p><b>Same-Currency Transfers only, and not by a check.</b> Both amounts on the Transfer
 * are denominated by the source Account, so a Transfer between two Currencies is reserved
 * and written with the wrong Currency in the credited column rather than refused. That hole
 * is deliberate and named in {@code docs/deferred.md}: ticket 26 is where an Exchange Rate
 * gives the credited side a figure of its own, and a refusal added here now is a rule ticket
 * 26 would have to reinterpret rather than delete.
 */
@Service
class FundsReservation {

	private final AccountLocking accounts;

	private final TransferRepository transfers;

	private final CheckLedger ledger;

	FundsReservation(AccountLocking accounts, TransferRepository transfers, CheckLedger ledger) {
		this.accounts = accounts;
		this.transfers = transfers;
		this.ledger = ledger;
	}

	/**
	 * Reserves the amount on the source Account and records the {@code PENDING} Transfer it
	 * is held for, in one transaction that writes both or neither.
	 *
	 * <p>The transaction is opened here rather than inherited, which is what {@link
	 * AccountLocking}'s mandatory propagation is checking for. Ticket 16 will widen it to
	 * carry the idempotency record's flip to {@code SUCCEEDED} in the same commit, per
	 * design decision 4.
	 *
	 * <p>The Check Ledger is opened last because its rows point at the Transfer's ID, and
	 * inside the same transaction because a {@code PENDING} Transfer with an empty checklist
	 * is one nothing will ever settle, expire or explain. {@link CheckLedger#openFor} refuses
	 * to run without a transaction, so the ordering is the only part of that left here.
	 *
	 * @throws hu.bankmonitor.payments.accounts.UnknownAccountException  if either Account ID
	 *                                                                  has no row
	 * @throws hu.bankmonitor.payments.accounts.InsufficientFundsException if the source
	 *                                                                  Account's Available
	 *                                                                  Balance does not
	 *                                                                  cover the amount
	 * @throws IllegalArgumentException if both IDs name the same Account
	 */
	@Transactional
	public Transfer reserve(ReservationRequest request) {
		LockedAccounts locked =
				accounts.lockForTransfer(request.sourceAccountId(), request.destinationAccountId());
		Money amount = new Money(request.amountMinorUnits(), locked.source().getCurrency());

		locked.source().reserve(amount);

		Transfer requested = transfers.save(new Transfer(request.sourceAccountId(),
				request.destinationAccountId(), amount, amount, request.requestedAt()));
		ledger.openFor(requested);
		return requested;
	}
}

package hu.bankmonitor.payments.transfers.checks;

import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import org.hibernate.annotations.JdbcTypeCode;
import org.hibernate.type.SqlTypes;

import java.util.Objects;

/**
 * One Check a Transfer requires, and how that Check has answered it.
 *
 * <p>A Transfer's rows together are its Check Ledger, and they are written when the
 * Transfer is: the ledger is a checklist fixed at request time, not a log that grows as
 * parties report things. The unique constraint on {@code (transfer_id, required_check)}
 * says the same in the table, and it is what will make a Check service's at-least-once
 * delivery safe to receive.
 *
 * <p><b>An unanswered Check has no Verdict, and the column is null.</b> The alternative —
 * a third {@code PENDING} constant on {@link Verdict}, which is the shape design decision
 * 8 sketched — would make "nobody has answered" one of the answers, and every reader would
 * then have to know which of the three is not really a Verdict. {@link
 * hu.bankmonitor.payments.transfers.TransferStatus} carries {@code PENDING} for the
 * opposite reason: a Transfer really is in that state. Nothing is in the state of having
 * given the null answer.
 *
 * <p><b>The Transfer is referenced by ID, not by association</b>, on {@code Transfer}'s own
 * precedent: a Transfer only ever leaves {@code PENDING} by a conditional update guarded on
 * the status it is leaving, and an association would offer a second way to reach one that
 * quietly skips that.
 *
 * <p><b>The identifier is surrogate rather than the pair that is unique</b>, on {@code
 * IdempotencyRecord}'s precedent: Spring Data decides between insert and merge from whether
 * the identifier is set, so an assigned key would turn every {@code save} into a
 * {@code SELECT} followed by an {@code UPDATE}. The uniqueness that matters is a named
 * constraint either way.
 *
 * <p>There is deliberately no mutator. Ticket 20 writes a Verdict as an update guarded on
 * the row still being unanswered, because two deliveries of the same Verdict have to leave
 * the Transfer advanced once; a setter would offer a second way to make that transition
 * that quietly is not atomic.
 */
@Entity
@Table(name = "check_ledger")
class CheckLedgerEntry {

	@Id
	@GeneratedValue(strategy = GenerationType.IDENTITY)
	private Long id;

	private Long transferId;

	// `check` is reserved in SQL, so the column this name produces is `required_check`.
	@Enumerated(EnumType.STRING)
	@JdbcTypeCode(SqlTypes.VARCHAR)
	private Check requiredCheck;

	// If left unannotated, JPA stores the verdict by ordinal. See design decision 29.
	@Enumerated(EnumType.STRING)
	@JdbcTypeCode(SqlTypes.VARCHAR)
	private Verdict verdict;

	protected CheckLedgerEntry() {
		// required by JPA
	}

	/**
	 * A row in any state it can hold, which is what {@link LedgerDecision#decide} is
	 * specified over and therefore has to be able to see.
	 *
	 * <p>Production never reaches this with a Verdict in hand — {@link #outstanding} is how
	 * a row comes into being, and the answer arrives later as an update. That is the
	 * distinction being drawn: constructing a row in a state is not the same operation as
	 * <em>transitioning</em> one into it, and only the transition has a race to lose.
	 */
	CheckLedgerEntry(Long transferId, Check requiredCheck, Verdict verdict) {
		this.transferId = Objects.requireNonNull(transferId, "a check is required of a transfer");
		this.requiredCheck = Objects.requireNonNull(requiredCheck, "a ledger row is one check");
		this.verdict = verdict;
	}

	/** Opens a Check on a Transfer with nobody having answered it yet. */
	static CheckLedgerEntry outstanding(Long transferId, Check requiredCheck) {
		return new CheckLedgerEntry(transferId, requiredCheck, null);
	}

	Long getId() {
		return id;
	}

	/** Whether this Check has said no — the one answer that ends a Transfer on its own. */
	boolean isRejected() {
		return verdict == Verdict.REJECTED;
	}

	/** Whether anyone has answered this Check at all, either way. */
	boolean isAnswered() {
		return verdict != null;
	}
}

